// Package sandbox ports the OS-level confinement policy used by Kilo Code
// (packages/kilo-sandbox). macOS runs commands through Seatbelt profiles
// generated by /usr/bin/sandbox-exec; unsupported platforms report
// unavailability instead of silently running unconfined.
package sandbox

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/hoxiai/hoxi/internal/hoxipaths"
)

type PathKind string

const (
	PathLiteral PathKind = "literal"
	PathSubtree PathKind = "subtree"
	// PathRegex is a Seatbelt regular expression over the resolved path.
	PathRegex PathKind = "regex"
)

type PathRule struct {
	Path string
	Kind PathKind
}

type FilesystemProfile struct {
	AllowWrite []PathRule
	DenyWrite  []PathRule
	DenyRead   []PathRule
	DenyNames  []string
	// NameDenyExemptions lists explicitly granted roots where DenyNames do not
	// apply, e.g. the repository's .git directory for a worktree session.
	NameDenyExemptions []PathRule
	TemporaryDirectory string
}

type NetworkMode string

const (
	NetworkAllow NetworkMode = "allow"
	NetworkDeny  NetworkMode = "deny"
)

type NetworkProfile struct {
	Mode NetworkMode
	// DenySockets are Unix sockets a confined command may not connect to,
	// even when outbound network access is allowed.
	DenySockets []PathRule
}

type Profile struct {
	Filesystem FilesystemProfile
	Network    NetworkProfile
}

func NormalizeNetworkMode(mode string) (NetworkMode, error) {
	switch strings.TrimSpace(strings.ToLower(mode)) {
	case "", string(NetworkDeny):
		return NetworkDeny, nil
	case string(NetworkAllow):
		return NetworkAllow, nil
	default:
		return "", errors.New("sandbox network mode must be allow or deny")
	}
}

// DefaultProfile mirrors Kilo Code's writable roots: the session workspace plus
// Hoxi state and the toolchain caches that CLIs need to run.
func DefaultProfile(workspace string, network NetworkMode, extraWritable ...string) (Profile, error) {
	workspace, err := canonicalDirectory(workspace)
	if err != nil {
		return Profile{}, err
	}
	if network == "" {
		network = NetworkDeny
	}
	roots := []string{workspace}
	roots = append(roots, extraWritable...)
	var nameDenyExemptions []PathRule
	var deny []PathRule
	for _, root := range extraWritable {
		root = strings.TrimSpace(root)
		if root == "" {
			continue
		}
		canonical, err := filepath.Abs(root)
		if err != nil {
			continue
		}
		if resolved, err := filepath.EvalSymlinks(canonical); err == nil {
			canonical = resolved
		}
		nameDenyExemptions = append(nameDenyExemptions, PathRule{Path: canonical, Kind: PathSubtree})
		if filepath.Base(canonical) == ".git" {
			deny = append(deny,
				PathRule{Path: filepath.Join(canonical, "hooks"), Kind: PathSubtree},
				PathRule{Path: filepath.Join(canonical, "info"), Kind: PathSubtree},
				PathRule{Path: filepath.Join(canonical, "config"), Kind: PathLiteral},
				PathRule{Path: filepath.Join(canonical, "config.lock"), Kind: PathLiteral},
			)
		}
	}
	for _, dir := range []string{
		hoxipaths.Home(),
		filepath.Join(hoxipaths.Home(), "sandbox"),
		filepath.Join(hoxipaths.Home(), "runtime"),
		os.TempDir(),
		"/private/tmp",
		"/private/var/folders",
	} {
		if dir != "" {
			roots = append(roots, dir)
		}
	}
	roots = append(roots, runtimeStateDirs()...)
	var allow []PathRule
	seen := make(map[string]bool)
	for _, root := range roots {
		root = strings.TrimSpace(root)
		if root == "" {
			continue
		}
		canonical, err := filepath.Abs(root)
		if err != nil {
			continue
		}
		if resolved, err := filepath.EvalSymlinks(canonical); err == nil {
			canonical = resolved
		}
		if seen[canonical] {
			continue
		}
		seen[canonical] = true
		allow = append(allow, PathRule{Path: canonical, Kind: PathSubtree})
	}
	allow = append(allow, PathRule{Path: "/dev", Kind: PathSubtree})
	for _, dir := range []string{
		DefaultRoot(),
		filepath.Join(hoxipaths.Home(), "sandbox"),
		hoxipaths.BinDir(),
		hoxipaths.EngineDataDir(),
		hoxipaths.EngineStateDir(),
	} {
		if dir != "" && dir != string(filepath.Separator) {
			deny = append(deny, PathRule{Path: dir, Kind: PathSubtree})
		}
	}
	deny = append(deny, protectedStateRules()...)
	return Profile{
		Filesystem: FilesystemProfile{
			AllowWrite:         allow,
			DenyWrite:          deny,
			DenyRead:           secretReadRules(workspace),
			DenyNames:          []string{".git"},
			NameDenyExemptions: nameDenyExemptions,
			TemporaryDirectory: "/private/tmp",
		},
		Network: NetworkProfile{Mode: network, DenySockets: credentialSocketRules()},
	}, nil
}

// credentialSocketRules are the Unix sockets that hand out credentials
// without reading a file: SSH agents (launchd's default agent, 1Password,
// Secretive, gpg-agent's ssh socket, the current SSH_AUTH_SOCK) and ssh
// ControlMaster connections under ~/.ssh. The runtime environment drops
// SSH_AUTH_SOCK, but the default socket path is discoverable, so the profile
// refuses the connection itself. Docker and other daemon sockets are not
// listed here.
func credentialSocketRules() []PathRule {
	rules := []PathRule{{Path: `^/private/tmp/com\.apple\.launchd\.[^/]+/Listeners$`, Kind: PathRegex}}
	if home, err := os.UserHomeDir(); err == nil && home != "" {
		if resolved, err := filepath.EvalSymlinks(home); err == nil {
			home = resolved
		}
		for _, dir := range []string{
			".ssh",
			".gnupg",
			filepath.Join("Library", "Group Containers", "2BUA8C4S2C.com.1password"),
			filepath.Join("Library", "Containers", "com.maxgoedjen.Secretive.SecretAgent"),
		} {
			rules = append(rules, PathRule{Path: filepath.Join(home, dir), Kind: PathSubtree})
		}
	}
	if sock := strings.TrimSpace(os.Getenv("SSH_AUTH_SOCK")); filepath.IsAbs(sock) {
		if resolved, err := filepath.EvalSymlinks(sock); err == nil {
			sock = resolved
		}
		rules = append(rules, PathRule{Path: sock, Kind: PathLiteral})
	}
	return rules
}

// protectedStateRules keeps confined commands from rewriting Hoxi's session
// store, provider config and engine database, or the approval hooks and
// settings that gate the runtimes, even though their parent directories stay
// writable for the CLIs' own session state.
func protectedStateRules() []PathRule {
	var rules []PathRule
	if hoxi := hoxipaths.Home(); hoxi != "" {
		rules = append(rules, PathRule{Path: filepath.Join(hoxi, "sessions"), Kind: PathSubtree})
		for _, name := range hoxipaths.ProtectedStateFiles() {
			rules = append(rules, PathRule{Path: filepath.Join(hoxi, name), Kind: PathLiteral})
		}
	}
	for _, file := range hoxipaths.DBFiles() {
		rules = append(rules, PathRule{Path: file, Kind: PathLiteral})
	}
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		return rules
	}
	for _, file := range []string{
		filepath.Join(home, ".claude", "settings.json"),
		filepath.Join(home, ".claude", "settings.local.json"),
		filepath.Join(home, ".gemini", "config", "hooks.json"),
	} {
		rules = append(rules, PathRule{Path: file, Kind: PathLiteral})
	}
	return rules
}

// secretReadRules are credential directories and files a sandboxed command
// must not read. Paths are under the real home directory, never a hard-coded
// username. Worktree .env files are denied at the worktree root and one level
// of common subdirectories; Seatbelt has no glob for ".env but not
// .env.example", so the example names are not listed and stay readable.
func secretReadRules(workspace string) []PathRule {
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		return nil
	}
	var rules []PathRule
	for _, dir := range []string{".ssh", ".aws", ".gnupg", ".kube", ".azure", filepath.Join(".config", "gh"), filepath.Join(".config", "gcloud")} {
		rules = append(rules, PathRule{Path: filepath.Join(home, dir), Kind: PathSubtree})
	}
	for _, file := range []string{
		filepath.Join(".docker", "config.json"),
		".netrc", ".npmrc", ".pypirc", ".git-credentials",
	} {
		rules = append(rules, PathRule{Path: filepath.Join(home, file), Kind: PathLiteral})
	}
	rules = append(rules, PathRule{Path: filepath.Join(home, ".cargo"), Kind: PathSubtree})
	rules = append(rules, PathRule{Path: filepath.Join(home, "Library", "Keychains"), Kind: PathSubtree})
	if hoxi := hoxipaths.Home(); hoxi != "" {
		for _, name := range hoxipaths.ProtectedStateFiles() {
			rules = append(rules, PathRule{Path: filepath.Join(hoxi, name), Kind: PathLiteral})
		}
		for _, file := range hoxipaths.DBFiles() {
			rules = append(rules, PathRule{Path: file, Kind: PathLiteral})
		}
	}
	rules = append(rules, worktreeEnvRules(workspace)...)
	return rules
}

func worktreeEnvRules(workspace string) []PathRule {
	if strings.TrimSpace(workspace) == "" {
		return nil
	}
	names := []string{".env", ".env.local", ".env.production", ".env.development"}
	dirs := []string{workspace, filepath.Join(workspace, "web"), filepath.Join(workspace, "client"), filepath.Join(workspace, "server")}
	var rules []PathRule
	for _, dir := range dirs {
		for _, name := range names {
			rules = append(rules, PathRule{Path: filepath.Join(dir, name), Kind: PathLiteral})
		}
	}
	return rules
}

// GitMetadataDir returns the git directory that commands in workspace must be
// able to write: the repository's own .git, or for a linked worktree the main
// repository's common .git directory.
func GitMetadataDir(workspace string) string {
	workspace = strings.TrimSpace(workspace)
	if workspace == "" {
		return ""
	}
	dotGit := filepath.Join(workspace, ".git")
	st, err := os.Stat(dotGit)
	if err != nil {
		return ""
	}
	if st.IsDir() {
		return dotGit
	}
	raw, err := os.ReadFile(dotGit)
	if err != nil {
		return ""
	}
	gitDir, ok := strings.CutPrefix(strings.TrimSpace(string(raw)), "gitdir:")
	if !ok {
		return ""
	}
	gitDir = strings.TrimSpace(gitDir)
	if !filepath.IsAbs(gitDir) {
		gitDir = filepath.Join(workspace, gitDir)
	}
	common := filepath.Clean(gitDir)
	if commonRaw, err := os.ReadFile(filepath.Join(common, "commondir")); err == nil {
		dir := strings.TrimSpace(string(commonRaw))
		if !filepath.IsAbs(dir) {
			dir = filepath.Join(common, dir)
		}
		common = filepath.Clean(dir)
	}
	if st, err := os.Stat(common); err != nil || !st.IsDir() {
		return ""
	}
	return common
}

func runtimeStateDirs() []string {
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		return nil
	}
	candidates := []string{
		filepath.Join(home, ".claude"),
		filepath.Join(home, ".claude.json"),
		filepath.Join(home, ".codebuddy"),
		filepath.Join(home, ".qoder"),
		filepath.Join(home, ".gemini"),
		filepath.Join(home, ".antigravity"),
		filepath.Join(home, ".cache"),
		filepath.Join(home, ".npm"),
		filepath.Join(home, "go", "pkg"),
		filepath.Join(home, "Library", "Caches"),
	}
	for _, envKey := range []string{"GOCACHE", "GOMODCACHE", "npm_config_cache"} {
		if v := strings.TrimSpace(os.Getenv(envKey)); v != "" && filepath.IsAbs(v) {
			candidates = append(candidates, v)
		}
	}
	var dirs []string
	for _, dir := range candidates {
		if strings.HasSuffix(dir, ".json") {
			if _, err := os.Stat(dir); err == nil {
				dirs = append(dirs, dir)
			}
			continue
		}
		// Runtime CLIs create these lazily; allow and pre-create them so the
		// sandbox can write its own session state on a fresh install.
		_ = os.MkdirAll(dir, 0o700)
		dirs = append(dirs, dir)
	}
	return dirs
}

func canonicalDirectory(directory string) (string, error) {
	directory = strings.TrimSpace(directory)
	if directory == "" {
		return "", errors.New("sandbox workspace is required")
	}
	if strings.HasPrefix(directory, "~") {
		home, err := os.UserHomeDir()
		if err != nil {
			return "", err
		}
		directory = filepath.Join(home, strings.TrimPrefix(directory, "~"))
	}
	abs, err := filepath.Abs(directory)
	if err != nil {
		return "", err
	}
	st, err := os.Stat(abs)
	if err != nil {
		return "", err
	}
	if !st.IsDir() {
		return "", fmt.Errorf("sandbox workspace is not a directory: %s", abs)
	}
	if resolved, err := filepath.EvalSymlinks(abs); err == nil {
		abs = resolved
	}
	return abs, nil
}

func DefaultRoot() string {
	base := hoxipaths.Home()
	if base == "" {
		base = os.TempDir()
	}
	return filepath.Join(base, "sandbox-policy")
}
